 if(!quote.trim()||quote.length>MAX_PASSAGE_QUOTE||!anchorValid(local,article))return{error:"The exact range does not match this eligible material."};
 const part=parts[0]!;if(part.kind!=="excerpt")return{anchor:local};const origin=part.excerpt,display=part.excerptDisplay;
 if(!origin||!display||origin.end-origin.start!==part.text.length)return{error:"Source excerpt provenance is unavailable; no origin range has been guessed."};
