export function captureBelongsToReading(anchor:PassageAnchor,article:Pick<WorkspaceRecord,"family"|"id">){return(anchor.articleId===article.id&&(anchor.recordFamily??"article")===article.family)||(anchor.displayReturn?.id===article.id&&anchor.displayReturn.recordFamily===article.family);}
